async function loadLatestSnapshot() {
  const response = await fetch(`./latest.json?refresh=${Date.now()}`, { cache: "no-store" });
  if (!response.ok) throw new Error(`HTTP ${response.status}`);
  const snapshot = await response.json();
  if (!snapshot.snapshotId || !Array.isArray(snapshot.recommendations)) throw new Error("Invalid snapshot payload");
  const refreshedData = window.adaptComassetSnapshot?.(snapshot);
  if (!refreshedData) throw new Error("Snapshot adapter unavailable");
  recommendations.splice(0, recommendations.length, ...refreshedData.recommendations);
  factorValues.splice(0, factorValues.length, ...Object.values(refreshedData.factorValues));
  if (!recommendations.some((item) => item.ticker === selectedTicker)) selectedTicker = recommendations[0]?.ticker;
  document.getElementById("snapshotAsOf").textContent = snapshot.asOf;
  renderCounts();
  renderRecommendations();
  renderTopIdeas();
  renderFactors();
  renderAuditList();
  renderDetail();
  renderSettings();
  drawAllocationChart();
  return snapshot;
}

async function refreshRecommendations() {
  const button = document.getElementById("refreshRecommendationsButton");
  const status = document.getElementById("refreshRecommendationsStatus");
  const label = button.querySelector("[data-i18n]");
  button.disabled = true;
  button.classList.add("refreshing");
  label.textContent = t("refreshingRecommendations");
  status.textContent = "";

  try {
    const run = await runServerRefresh("recommendations", status);
    const snapshot = await loadLatestSnapshot();
    const changed = Boolean(run.outputs?.recommendations?.changed);
    const pending = changed && run.outputs?.recommendations?.codexAuditStatus !== "reviewed";
    status.textContent = `${t(changed ? "recommendationsRefreshed" : "recommendationsUnchanged")} · ${snapshot.snapshotId}${pending ? ` · ${t("codexReviewPending")}` : ""}`;
    writeAccessEvent("recommendations_refresh", { runId: run.runId, snapshotId: snapshot.snapshotId, changed });
  } catch (error) {
    status.textContent = error.code === "SERVER_REQUIRED"
      ? t("refreshRequiresServer")
      : error.code === "PERMISSION_DENIED"
        ? t("refreshPermissionDenied")
        : t("recommendationsRefreshFailed");
    button.title = error.message;
  } finally {
    button.disabled = !hasPermission("run_pipeline");
    button.classList.remove("refreshing");
    label.textContent = t("refreshRecommendations");
  }
}

