function calculateSimulation(strategyOverride) {
  const inputs = getSimulationInputs();
  const strategy = strategyOverride || inputs.strategy;
  if (!window.ComassetBacktest || !backtestData) {
    throw new Error("Historical backtest data is unavailable.");
  }
  const result = window.ComassetBacktest.runBacktest(backtestData, {
    strategy,
    initialCapital: inputs.initialCapital,
    monthlyContribution: inputs.monthlyContribution,
    rebalance: inputs.rebalance,
    topN: 5,
    slippage: 0.0005,
  });
  const curveByDate = Object.fromEntries(result.equityCurve.map((point) => [point.date, point]));

  return {
    points: result.equityCurve.map((point) => point.value),
    pointDates: result.equityCurve.map((point) => point.date),
    rows: result.rebalanceLog.map((row) => ({
      date: row.date,
      contribution: row.contribution,
      action: row.tickers.length ? row.tickers.join(" / ") : "CASH",
      value: curveByDate[row.date]?.value || 0,
      snapshotId: row.snapshotId,
    })),
    monthlyRows: result.monthlyRows,
    strategy,
    finalValue: result.summary.finalValue,
    invested: result.summary.investedCapital,
    totalReturn: result.summary.timeWeightedReturn,
    maxDrawdown: result.summary.maxDrawdown,
    maxDrawdownWindow:
      result.summary.maxDrawdownStart && result.summary.maxDrawdownEnd
        ? `${result.summary.maxDrawdownStart} - ${result.summary.maxDrawdownEnd}`
        : "-",
    sharpe: result.summary.sharpe,
    turnover: result.summary.turnoverTrades,
    period: result.period,
    warnings: result.warnings,
    sourceSnapshotIds: result.sourceSnapshotIds,
    raw: result,
  };
}

function readLocalSimulationRuns() {
  try {
    const runs = JSON.parse(localStorage.getItem(simulationRunsKey));
    return Array.isArray(runs) ? runs : [];
  } catch {
    return [];
  }
}

function saveCurrentSimulation() {
  if (!currentSimulation?.raw) return;
  const savedAt = new Date().toISOString();
  const run = {
    runId: `${savedAt.replace(/[-:.]/g, "")}-${currentSimulation.strategy}-${currentMemberId}`,
    owner: currentMemberId,
    ownerName: currentMember().name,
    storage: "browser_localStorage",
    savedAt,
    ...currentSimulation.raw,
  };
  const runs = [run, ...readLocalSimulationRuns()].slice(0, 30);
  localStorage.setItem(simulationRunsKey, JSON.stringify(runs));
  writeAccessEvent("simulation_run_save", { runId: run.runId, strategy: run.strategy });
  renderSimulationHistory();
  renderSettings();
}

function renderSimulationHistory() {
  const localRuns = readLocalSimulationRuns().filter((run) => run.owner === currentMemberId);
  const pipelineRuns = backtestData?.savedRuns || [];
  const runs = [...localRuns, ...pipelineRuns]
    .sort((a, b) => String(b.savedAt || b.generatedAt).localeCompare(String(a.savedAt || a.generatedAt)))
    .slice(0, 12);
  const container = document.getElementById("simulationHistoryRows");
  if (!runs.length) {
    container.innerHTML = `<p class="empty-simulation-history">${t("noSavedRuns")}</p>`;
    return;
  }
  container.innerHTML = runs
    .map(
      (run) => `
        <article class="simulation-history-row">
          <div>
            <strong>${strategyLabel(run.strategy)}</strong>
            <span>${escapeHtml(run.ownerName || run.owner || "pipeline")} · ${escapeHtml(
              String(run.savedAt || run.generatedAt || "").replace("T", " ").slice(0, 16)
            )}</span>
          </div>
          <div><span>${t("backtestPeriod")}</span><strong>${run.period?.start || "-"} - ${run.period?.end || "-"}</strong></div>
          <div><span>${t("finalValue")}</span><strong>${formatCurrency(run.summary?.finalValue || 0)}</strong></div>
          <div><span>${t("totalReturn")}</span><strong>${formatPercent(run.summary?.timeWeightedReturn || 0)}</strong></div>
          <div><span>${t("snapshotsUsed")}</span><strong>${escapeHtml((run.sourceSnapshotIds || []).join(", ") || "-")}</strong></div>
        </article>
      `
    )
    .join("");
}

function renderSimulation() {
  currentSimulation = calculateSimulation();
  document.getElementById("finalValueMetric").textContent = formatCurrency(currentSimulation.finalValue);
  document.getElementById("totalReturnMetric").textContent = formatPercent(currentSimulation.totalReturn);
  document.getElementById("maxDrawdownMetric").textContent = formatPercent(currentSimulation.maxDrawdown);
  document.getElementById("sharpeMetric").textContent = currentSimulation.sharpe.toFixed(2);

  const comparisonKeys = ["mixed", "ultra", "benchmark"];
  const comparisons = comparisonKeys.map((key) => calculateSimulation(key));
  document.getElementById("comparisonRows").innerHTML = `
    <div class="comparison-header">
      <span>${t("strategy")}</span>
      <span>${t("finalValue")}</span>
      <span>${t("totalReturn")}</span>
      <span>${t("maxDrawdown")}</span>
      <span>${t("turnover")}</span>
    </div>
    ${comparisons
      .map(
        (item) => `
          <div class="comparison-row ${item.strategy === currentSimulation.strategy ? "active" : ""}">
            <strong>${strategyLabel(item.strategy)}</strong>
            <span>${formatCurrency(item.finalValue)}</span>
            <span>${formatPercent(item.totalReturn)}</span>
            <span>${formatPercent(item.maxDrawdown)} · ${item.maxDrawdownWindow}</span>
            <span>${item.turnover}</span>
          </div>
        `
      )
      .join("")}
  `;

  document.getElementById("monthlyReturnRows").innerHTML = `
    <div class="monthly-return-header">
      <span>${t("month")}</span>
      <span>${t("totalReturn")}</span>
      <span>${t("portfolioValue")}</span>
    </div>
    ${currentSimulation.monthlyRows
      .map(
        (row) => `
          <div class="monthly-return-row">
            <span>${row.month}</span>
            <span>${formatPercent(row.return)}</span>
            <strong>${formatCurrency(row.value)}</strong>
          </div>
        `
      )
      .join("")}
  `;

  const rows = document.getElementById("tradeLogRows");
  rows.innerHTML = `
    <div class="trade-log-header">
      <span>${t("month")}</span>
      <span>${t("contribution")}</span>
      <span>${t("rebalanceAction")}</span>
      <span>${t("portfolioValue")}</span>
    </div>
    ${currentSimulation.rows
      .map(
        (row) => `
          <div class="trade-log-row">
            <span>${row.date}</span>
            <span>${formatCurrency(row.contribution)}</span>
            <span>${row.action}<small>${row.snapshotId || "-"}</small></span>
            <strong>${formatCurrency(row.value)}</strong>
          </div>
        `
      )
      .join("")}
  `;
  document.getElementById("simulationWarningRows").innerHTML = currentSimulation.warnings?.length
    ? `<div class="simulation-warning"><strong>${t("simulationWarnings")}</strong><ul>${currentSimulation.warnings
        .map((warning) => `<li>${escapeHtml(warning)}</li>`)
        .join("")}</ul></div>`
    : "";
  renderSimulationHistory();
}

function drawSimulationChart() {
  const canvas = document.getElementById("simulationChart");
  const ctx = canvas.getContext("2d");
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  const comparisonKeys = ["mixed", "ultra", "benchmark"];
  const series = comparisonKeys.map((key) => calculateSimulation(key));
  const allPoints = series.flatMap((item) => item.points);
  if (!allPoints.length) return;
  const rawMin = Math.min(...allPoints);
  const rawMax = Math.max(...allPoints);
  const padding = Math.max(1, (rawMax - rawMin) * 0.2, rawMax * 0.01);
  const min = rawMin - padding;
  const max = rawMax + padding;
  const left = 42;
  const top = 24;
  const width = canvas.width - 72;
  const height = canvas.height - 64;

  ctx.strokeStyle = "#dbe2dd";
  ctx.lineWidth = 1;
  for (let i = 0; i < 4; i += 1) {
    const y = top + (height / 3) * i;
    ctx.beginPath();
    ctx.moveTo(left, y);
    ctx.lineTo(left + width, y);
    ctx.stroke();
  }

  const colors = {
    mixed: "#207a5c",
    ultra: "#285f9f",
    benchmark: "#9d752d",
    qqq: "#7b5fb2",
    cash: "#69756f",
  };
  series.forEach((item) => {
    ctx.strokeStyle = colors[item.strategy] || "#207a5c";
    ctx.lineWidth = item.strategy === currentSimulation?.strategy ? 4 : 2;
    ctx.beginPath();
    item.points.forEach((value, index) => {
      const x = item.points.length === 1 ? left + width / 2 : left + (width / (item.points.length - 1)) * index;
      const y = top + height - ((value - min) / (max - min)) * height;
      if (index === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();
  });

  ctx.fillStyle = "#17201c";
  ctx.font = "700 14px system-ui";
  ctx.fillText(formatCurrency(currentSimulation?.points.at(-1) || 0), left + width - 78, top + 18);
  ctx.fillStyle = "#69756f";
  ctx.font = "12px system-ui";
  ctx.fillText(currentSimulation?.period?.end || "-", left + width - 72, top + height + 28);
  ctx.fillText(currentSimulation?.period?.start || "-", left - 8, top + height + 28);
}

function drawCharts() {
  drawAllocationChart();
  drawPortfolioChart();
  drawSimulationChart();
}

